_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("layernorm_kernel")

class ModelNew(nn.Module):
    def __init__(self, normalized_shape):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        normalized_ndim = len(self.normalized_shape)
        if normalized_ndim > 0:
            outer_shape = x.shape[:-normalized_ndim]
        else:
            outer_shape = x.shape

        batch_size = 1
        for d in outer_shape:
            batch_size *= d

        n = 1
        for d in self.normalized_shape:
            n *= d

        x_c = x.contiguous()
        weight_c = self.weight.contiguous()
        bias_c = self.bias.contiguous()

        output = torch.empty(x_c.shape, dtype=x_c.dtype, device=x_c.device)

        module = _get_ptx_module()
        module.launch(
            "layernorm_kernel",
            grid=(batch_size, 1, 1),
            block=(1024, 1, 1),
            arguments=[x_c, output, weight_c, bias_c, i32(n), f32(self.eps)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output

